INSERT OR IGNORE INTO manual_sections
  (manual_key, section_key, title, body, sort_order, version, updated_by, updated_at)
VALUES
  ('owner','escalation-knowledge-pipeline','Escalation Inbox နှင့် multilingual FAQ knowledge workflow','/cases ကို private bot chat သို့မဟုတ် active Staff Inbox group ထဲတွင် အသုံးပြုနိုင်ပါတယ်။ ဒီ command က Open, Claimed, Resolved နှင့် All escalation cases ကို pager view နဲ့ ပြပါတယ်။ Case detail မှာ original user identity, language, question, stored reason, status နှင့် linked FAQ ရှိပါက FAQ key ကို ကြည့်နိုင်ပါတယ်။\n\n＋ Add as FAQ ကိုနှိပ်လျှင် escalation ရဲ့ original language/question ကို FAQ draft အဖြစ် prefill လုပ်ပေးပါတယ်။ Find Related FAQ က လက်ရှိ approved FAQ နဲ့ match စစ်ပြီး ရှိပြီးသား FAQ ကို review/edit လုပ်ဖို့ သို့မဟုတ် FAQ အသစ်စဖို့ ချိတ်ပေးပါတယ်။\n\nFAQ Add/Edit မှာ မြန်မာ၊ English၊ 简体中文 ထဲက မိမိယုံကြည်စိတ်ချစွာ ရေးနိုင်တဲ့ source language တစ်မျိုးကို ရွေးပြီး authoritative question + answer ကိုရေးနိုင်ပါတယ်။ ✨ Generate other 2 languages က configured Primary AI ကိုသုံးပြီး ကျန်ဘာသာနှစ်မျိုးကို draft ပြုလုပ်ပေးပြီး Primary မအောင်မြင်ပါက configured Fallback ကိုကြိုးစားပါတယ်။ AI output သည် draft သာဖြစ်ပြီး policy facts အသစ်ထည့်ခွင့်မရှိပါ။ Preview ထဲမှာ သုံးဘာသာလုံးကို review လုပ်ပြီး ✅ Approve & Save နှိပ်မှသာ canonical FAQ အဖြစ် သိမ်းပြီး live knowledge ထဲဝင်ပါတယ်။\n\nAI unavailable/timeout/failure ဖြစ်ပါက source draft မပျောက်ပါ။ Retry AI သို့မဟုတ် ✍ Fill/Edit translations manually ကိုသုံးပြီး ကျန်ဘာသာနှစ်မျိုးကို manual ဖြည့်နိုင်ပါတယ်။ AI availability က FAQ creation ကို block မလုပ်ရပါ။ Existing individual-field edit workflow ကို precise corrections အတွက် ဆက်သုံးနိုင်ပါတယ်။\n\nFAQ management နှင့် /cases archive ကို Bot Owner နှင့် Sudo Admins သုံးနိုင်ပါတယ်။ AI provider/key/model configuration ကိုတော့ Owner က /ai မှာ စီမံပါတယ်။',80,1,0,CURRENT_TIMESTAMP),
  ('admin','escalation-knowledge-pipeline','Escalation Inbox မှ FAQ အသစ်တည်ဆောက်ခြင်း','/cases ကို bot private chat သို့မဟုတ် active Staff Inbox group ထဲတွင် သုံးပြီး Open, Claimed, Resolved သို့မဟုတ် All cases ကို pager view နဲ့ ကြည့်နိုင်ပါတယ်။ Case detail မှာ user question နဲ့ escalation reason ကို review လုပ်ပြီး ＋ Add as FAQ သို့မဟုတ် Find Related FAQ ကိုရွေးနိုင်ပါတယ်။\n\nFAQ အသစ်/ပြင်ဆင်မှုအတွက် မိမိတတ်ကျွမ်းတဲ့ မြန်မာ၊ English သို့မဟုတ် 简体中文 တစ်မျိုးကို source language အဖြစ်ရွေးပါ။ Source question/answer ကိုရေးပြီး ✨ Generate other 2 languages ကိုနှိပ်လျှင် configured AI က ကျန်ဘာသာနှစ်မျိုးကို draft ဖြည့်ပေးပါတယ်။ AI result ကို official fact အဖြစ် မယူရပါ။ Preview သုံးဘာသာလုံးကိုစစ်ပြီး ✅ Approve & Save နှိပ်မှသာ canonical FAQ အဖြစ် live ဖြစ်ပါတယ်။\n\nAI မရပါက draft မပျောက်ပါ။ Retry AI သို့မဟုတ် ✍ Fill/Edit translations manually ကိုသုံးပြီး ဆက်လုပ်နိုင်ပါတယ်။ AI failure ကြောင့် FAQ တင်မရတာ မဖြစ်ရပါ။ Individual-field edit ကိုလည်း အသေးစိတ် correction အတွက် ဆက်သုံးနိုင်ပါတယ်။',80,1,0,CURRENT_TIMESTAMP);
